14	/**
15	 * Pure hook handlers for every Claude Code lifecycle event Redutok uses.
16	 * Fail-open is the law here: a dead sidecar means the hook answers allow (or
17	 * empty) within LIMITS.HOOK_FAIL_OPEN_MS and the session runs vanilla.
18	 */
19	
20	export interface HookDeps {
21	  target: SidecarTarget;
22	  dcpDir: string;
23	  /** Sidecar probe budget; defaults to the 50ms fail-open limit. */
24	  timeoutMs?: number;
25	}
26	
27	export interface HookOutput {
28	  hookSpecificOutput?: {
29	    hookEventName: string;
30	    additionalContext?: string;
31	    permissionDecision?: 'allow' | 'deny';
32	    permissionDecisionReason?: string;
33	    updatedInput?: Record<string, unknown>;
34	  };
35	  summaryLine?: string;
36	  /** Multi-line session receipt printed under the summary line on Stop. */
37	  receiptBlock?: string;
38	}
39	
40	/** Reads below this pass untouched without even probing the sidecar. */
41	export const SMALL_READ_BYTES = 16_384;
42	/** Reads above this are redirected to dcp__read; between, updatedInput caps the read. */
43	export const LARGE_READ_BYTES = 65_536;
44	
45	const EXPENSIVE_BASH = /\b(tsc|vitest|jest|pytest|cargo (?:build|test)|go (?:build|test)|(?:pnpm|npm|yarn) (?:run )?(?:build|test|lint))\b/;
46	
47	async function sidecarUp(deps: HookDeps): Promise<boolean> {
48	  const res = await sidecarRequest(deps.target, 'GET', '/health', undefined, {
49	    timeoutMs: deps.timeoutMs ?? LIMITS.HOOK_FAIL_OPEN_MS,
50	  });
51	  return res.ok && res.status === 200;
52	}
53	
54	/**
55	 * Registers the transcript session id with the sidecar so artifacts and audit
56	 * events are attributed to it (the MCP server never learns the transcript id).
57	 * Fail-open like every hook path; a dead sidecar costs one timed-out probe.
58	 */
59	async function registerSession(sessionId: string | undefined, deps: HookDeps): Promise<void> {
60	  if (sessionId === undefined || sessionId === '') return;
61	  await sidecarRequest(
62	    deps.target,
63	    'POST',
64	    '/notify',
65	    { kind: 'session-start', sessionId },
66	    { timeoutMs: deps.timeoutMs ?? LIMITS.HOOK_FAIL_OPEN_MS },
67	  );
68	}
69	
70	export async function handleSessionStart(
71	  input: { source?: string; session_id?: string },
72	  deps: HookDeps,
73	): Promise<HookOutput> {
74	  await registerSession(input.session_id, deps);
75	  const protocolPath = path.join(deps.dcpDir, 'protocol.md');
76	  if (!existsSync(protocolPath)) return {};
77	  const block = readFileSync(protocolPath, 'utf8');
78	  const source = input.source ?? 'startup';
79	  const prefix =
80	    source === 'compact' || source === 'resume'
81	      ? `Redutok protocol re-injected after ${source}.\n\n`
82	      : '';
83	  let codexInjection = '';
84	  try {
85	    const root = path.dirname(path.resolve(deps.dcpDir));
86	    const { codex } = readCodex(root);
87	    if (codex !== undefined) codexInjection = '\n\n' + buildCodexInjection(codex);
88	  } catch {
89	    codexInjection = '';
90	  }
91	  return {
92	    hookSpecificOutput: {
93	      hookEventName: 'SessionStart',
94	      additionalContext: prefix + block + codexInjection,
95	    },
96	  };
97	}
98	
99	export async function handlePreToolUse(
100	  input: { tool_name?: string; tool_input?: Record<string, unknown> },
101	  deps: HookDeps,
102	): Promise<HookOutput> {
103	  const tool = input.tool_name ?? '';
104	  const args = input.tool_input ?? {};
105	  const deny = (reason: string): HookOutput => ({
106	    hookSpecificOutput: {
107	      hookEventName: 'PreToolUse',
108	      permissionDecision: 'deny',
109	      permissionDecisionReason: reason,
110	    },
111	  });
112	
113	  try {
114	    if (tool === 'Read') {
115	      const filePath = String(args['file_path'] ?? '');
116	      if (filePath === '' || !existsSync(filePath)) return {};
117	      const size = statSync(filePath).size;
118	      if (size <= SMALL_READ_BYTES) return {};
119	      if (!(await sidecarUp(deps))) return {};
120	      if (size > LARGE_READ_BYTES) {
121	        return deny(
122	          `File is ${Math.round(size / 1024)}KB. Call dcp__read("${filePath}") for a distilled skeleton with a zoom handle instead of reading it raw.`,
123	        );
124	      }
125	      return {
126	        hookSpecificOutput: {
127	          hookEventName: 'PreToolUse',
128	          permissionDecision: 'allow',
129	          updatedInput: { ...args, limit: 400 },
130	        },
131	      };
132	    }
133	    if (tool === 'Write') {
134	      // Output discipline, architecture 6.1: full rewrites of large existing
135	      // files draw emit-a-patch guidance; new files always pass.
136	      const filePath = String(args['file_path'] ?? '');
137	      const content = String(args['content'] ?? '');
138	      if (
139	        filePath !== '' &&
